(()=>{'use strict';
let privacyVisible=false;const KEY='financas.v2', $=s=>document.querySelector(s), brl=n=>privacyVisible?(+n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'••••••', esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mn=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'], palette=['#d97757','#2f6f5e','#d4a64a','#6f86a6','#8a78a8','#c47e9b','#779b89','#a78b6d'];
const cols={gastos:[['nome','Descrição','t'],['dia','Dia','d'],['tipo','Pagamento','tipo'],['cat','Categoria','cat'],['valor','Valor','n']],fixos:[['nome','Descrição','t'],['pago','Pago','b'],['dia','Dia','d'],['tipo','Pagamento','tipo'],['cat','Categoria','cat'],['valor','Valor','n']],parcelas:[['nome','Descrição','t'],['parc','Parcela','t'],['dia','Dia','d'],['tipo','Pagamento','tipo'],['cat','Categoria','cat'],['valor','Valor','n']]};
const clone=x=>JSON.parse(JSON.stringify(x));let S,cur='painel',timer,filter='todas',projectionYear=new Date().getFullYear();
function valid(x){return x&&Array.isArray(x.keys)&&x.months&&Array.isArray(x.debts)&&Array.isArray(x.cats)&&Array.isArray(x.tipos)}
function normalize(x){x.goals=Array.isArray(x.goals)?x.goals:[];x.banks=Array.isArray(x.banks)?x.banks:[];x.subscriptions=Array.isArray(x.subscriptions)?x.subscriptions:[];x.profile={nome:'Caio Luiz da Silva',chamado:'Caio',foto:'',salarioBase:1640,bonusBase:0,vrDia:36.4,vaMensal:336,pagamento:'5º dia útil',...(x.profile||{})};x.tipos=[...new Set([...(x.tipos||[]),'Débito','Pix','Caixa','Nubank','Mercado Pago','Credi','Itaú','Santander','XP','Bradesco','PicPay','RecargaPay','Neon','Inter'])];x.keys=[...new Set(x.keys)].sort();x.debts=x.debts.map(d=>({...d,nome:d.nome||'Nova dívida',valor:Math.max(0,+d.valor||0),inicial:Math.max(+d.inicial||+d.valor||0,+d.valor||0),historico:Array.isArray(d.historico)?d.historico:[],vencimento:d.vencimento||'',observacao:d.observacao||''}));x.keys.forEach(k=>{let m=x.months[k];if(m){['gastos','fixos','parcelas'].forEach(a=>{if(!Array.isArray(m[a]))m[a]=[]});m.esperado=m.esperado||{};m.nomeMes=m.nomeMes||'';m.aportesMetas=Array.isArray(m.aportesMetas)?m.aportesMetas:[];if(m.salary===undefined||m.salary===0)m.salary=x.profile.salarioBase;if(m.bonus===undefined)m.bonus=x.profile.bonusBase;if(m.valeAlimentacao===undefined||m.valeAlimentacao===0)m.valeAlimentacao=x.profile.vaMensal;m.investimentos=Array.isArray(m.investimentos)?m.investimentos:[];m.vrPeriodos=Array.isArray(m.vrPeriodos)?m.vrPeriodos:[]}});['Caixa','Nubank','Mercado Pago','Credi','Itaú','Santander','XP','Bradesco','PicPay','RecargaPay','Neon','Inter'].forEach((nome,i)=>{if(!x.banks.some(b=>b.nome===nome))x.banks.push({id:'b-default-'+i,nome,tipo:nome==='XP'?'Corretora':'Banco',identificador:'',nota:''})});return x}
try{let j=JSON.parse(localStorage.getItem(KEY));if(valid(j))S=normalize(j)}catch(e){}if(!S)S=normalize(clone(window.SEED));else{try{const migration='financas.seed-months-v1';if(!localStorage.getItem(migration)){const base=normalize(clone(window.SEED));base.keys.forEach(k=>{if(!S.keys.includes(k)){if(!S.months[k]&&base.months[k])S.months[k]=clone(base.months[k]);S.keys.push(k)}});S.keys=[...new Set(S.keys)].sort();localStorage.setItem(KEY,JSON.stringify(S));localStorage.setItem(migration,'1')}}catch(e){}}
let dateFilter={from:'',to:''},calendarDate=new Date();try{if(!localStorage.getItem('financas.clean-months-v1')){S.keys.forEach(k=>{let o=S.months[k]||{};S.months[k]={salary:0,bonus:0,valeRefeicao:0,valeAlimentacao:0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[],nomeMes:o.nomeMes||''}});save();localStorage.setItem('financas.clean-months-v1','1')}}catch(e){}
const today=(()=>{let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')})(),short=k=>{let[y,m]=k.split('-');return mn[+m-1]+'/'+y.slice(2)},full=k=>{let[y,m]=k.split('-');return (S&&S.months&&S.months[k]&&S.months[k].nomeMes)||new Date(+y,+m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})};
cur=S.keys.includes(today)?today:'painel';
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));$('#saved').classList.add('on');clearTimeout(timer);timer=setTimeout(()=>$('#saved').classList.remove('on'),1500)}catch(e){alert('Não foi possível salvar. Exporte um backup para proteger seus dados.')}}
function M(k){if(!S.months[k]){let i=S.keys.indexOf(k),p=S.months[S.keys[i-1]];S.months[k]={salary:S.profile?.salarioBase??p?.salary??0,bonus:S.profile?.bonusBase||0,valeRefeicao:0,valeAlimentacao:S.profile?.vaMensal||0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,investimentos:[],vrPeriodos:[],esperado:{},aportesMetas:[]}}let m=S.months[k];m.aportesMetas=Array.isArray(m.aportesMetas)?m.aportesMetas:[];m.investimentos=Array.isArray(m.investimentos)?m.investimentos:[];m.vrPeriodos=Array.isArray(m.vrPeriodos)?m.vrPeriodos:[];let added=false;(S.subscriptions||[]).filter(s=>s.ativo!==false&&(!s.inicio||k>=s.inicio)).forEach(s=>{if(!m.fixos.some(r=>r.subscriptionId===s.id||r.nome===s.nome)){m.fixos.push({nome:s.nome,dia:s.dia,tipo:s.tipo,cat:s.cat,valor:s.valor,pago:false,subscriptionId:s.id});added=true}});if(added&&typeof save==='function'&&$('#saved'))save();return m}
const color=c=>palette[Math.max(0,S.cats.indexOf(c))%palette.length];
function calc(k){let m=M(k),items=[...m.gastos,...m.fixos,...m.parcelas],cats={},types={};items.forEach(r=>{cats[r.cat]=(cats[r.cat]||0)+(+r.valor||0);types[r.tipo]=(types[r.tipo]||0)+(+r.valor||0)});let gasto=items.reduce((a,r)=>a+(+r.valor||0),0),entradas=(+m.salary||0)+(+m.bonus||0)+(+m.valeRefeicao||0)+(+m.valeAlimentacao||0)+(+m.valeReembolso||0),inv=(+m.reserva||0)+(+m.rendaFixa||0)+(m.aportesMetas||[]).reduce((a,r)=>a+(+r.valor||0),0);return{m,cats,types,gasto,entradas,inv,saldo:entradas-gasto-inv}}
function button(text,action,kind='secondary',extra=''){return '<button class="button '+kind+'" data-action="'+action+'" '+extra+'>'+text+'</button>'}
function head(kicker,title,desc,action=''){return '<header class="page-head"><div><p class="eyebrow">'+kicker+'</p><h1>'+title+'</h1><p class="lede">'+desc+'</p></div>'+action+'</header>'}
function metric(label,value,sub='',kind=''){return '<article class="metric '+kind+'"><span>'+label+'</span><strong>'+value+'</strong><small>'+sub+'</small></article>'}

function openForm(title,fields,values,onSave){let old=document.getElementById('finance-form-dialog');if(old)old.remove();let d=document.createElement('dialog');d.id='finance-form-dialog';d.className='finance-dialog';d.innerHTML='<form method="dialog"><div class="dialog-head"><h2>'+esc(title)+'</h2><button type="button" id="form-close">×</button></div><div class="dialog-fields">'+fields.map(f=>'<label>'+esc(f.label)+(f.type==='textarea'?'<textarea name="'+f.name+'">'+esc(values[f.name]||'')+'</textarea>':'<input name="'+f.name+'" type="'+(f.type||'text')+'" value="'+esc(values[f.name]??'')+'" '+(f.required?'required':'')+' '+(f.min!==undefined?'min="'+f.min+'"':'')+' '+(f.step?'step="'+f.step+'"':'')+'>')+'</label>').join('')+'</div><div class="dialog-actions"><button type="button" id="form-cancel">Cancelar</button><button type="submit" class="button primary">Salvar</button></div></form>';document.body.appendChild(d);d.querySelector('#form-close').onclick=d.querySelector('#form-cancel').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.currentTarget),v={};fields.forEach(f=>v[f.name]=f.type==='number'?(+fd.get(f.name)||0):String(fd.get(f.name)||'').trim());if(onSave(v)!==false){d.close();render()}};d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()}
function editProfile(){let p={nome:'Caio Luiz da Silva',chamado:'Caio',foto:'',salarioBase:1640,bonusBase:0,vrDia:36.4,vaMensal:336,pagamento:'5º dia útil',...S.profile};openForm('Meu perfil e dados financeiros',[{name:'nome',label:'Nome completo',required:true},{name:'chamado',label:'Como quer ser chamado?',required:true},{name:'foto',label:'URL direta da foto (https://...)'},{name:'salarioBase',label:'Salário-base mensal (R$)',type:'number',min:0,step:'.01',required:true},{name:'bonusBase',label:'Bônus mensal recorrente (R$)',type:'number',min:0,step:'.01'},{name:'vrDia',label:'Vale-refeição por dia (R$)',type:'number',min:0,step:'.01'},{name:'vaMensal',label:'Vale-alimentação mensal (R$)',type:'number',min:0,step:'.01'},{name:'pagamento',label:'Quando recebe o salário'}],p,v=>{S.profile={...p,...v,salarioBase:+v.salarioBase||0,bonusBase:+v.bonusBase||0,vrDia:+v.vrDia||0,vaMensal:+v.vaMensal||0};S.keys.forEach(k=>{let m=M(k);m.salary=S.profile.salarioBase;m.bonus=S.profile.bonusBase;m.valeAlimentacao=S.profile.vaMensal});save()})}
function clearAllMonths(){if(!confirm('Zerar os lançamentos de todos os meses? Os meses, bancos, dívidas, metas e assinaturas serão mantidos.'))return;S.keys.forEach(k=>{let old=S.months[k]||{};S.months[k]={salary:0,bonus:0,valeRefeicao:0,valeAlimentacao:0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[],nomeMes:old.nomeMes||''}});save();go('painel')}
function exportCSV(){let rows=[['Mês','Tipo','Descrição','Vencimento','Valor','Pago','Forma de pagamento','Categoria']];S.keys.forEach(k=>{let m=S.months[k]||{};[['Gasto',m.gastos],['Conta fixa',m.fixos],['Parcela',m.parcelas]].forEach(([t,ls])=>(ls||[]).forEach(x=>rows.push([k,t,x.nome,x.dia,x.valor,x.pago?'Sim':'Não',x.tipo,x.cat])));[['Salário',m.salary],['Vale-refeição',m.valeRefeicao],['Vale-alimentação',m.valeAlimentacao],['Vale-reembolso',m.valeReembolso]].forEach(([n,v])=>rows.push([k,'Entrada',n,'',v||0,'','','']))});let csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n'),a=document.createElement('a'),u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='financas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportPDF(){let w=window.open('','_blank');if(!w){alert('Permita a abertura de janelas para gerar o PDF.');return}let rows=S.keys.map(k=>{let c=calc(k);return '<tr><td>'+esc(full(k))+'</td><td>'+brl(c.entradas)+'</td><td>'+brl(c.gasto)+'</td><td>'+brl(c.saldo)+'</td></tr>'}).join('');w.document.write('<html><meta charset="utf-8"><title>Relatório financeiro</title><style>body{font:12px Arial;padding:25px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}</style><h1>Relatório financeiro</h1><table><tr><th>Mês</th><th>Entradas</th><th>Despesas</th><th>Saldo</th></tr>'+rows+'</table><p>Use “Salvar como PDF” na impressão.</p></html>');w.document.close();w.print()}
function annualChart(rows){let mx=Math.max(1,...rows.flatMap(x=>[x.entradas,x.gasto]));return '<section class="panel annual-chart-panel"><h2>Receitas x despesas</h2><div class="annual-bars">'+rows.map(r=>'<div class="annual-bar-col"><div class="annual-bar-pair"><i class="income" style="height:'+(r.entradas/mx*100)+'%"></i><i class="expense" style="height:'+(r.gasto/mx*100)+'%"></i></div><small>'+short(r.k).split('/')[0]+'</small></div>').join('')+'</div><div class="chart-key"><span>● Entradas</span><span>● Gastos</span></div></section>'}

function numInput(k,f,v){return '<input class="inline-number" type="number" min="0" step=".01" value="'+(+v||0)+'" data-change="month" data-month="'+k+'" data-field="'+f+'">'}
function cell(k,key,i,c,r){let[f,label,t]=c,attrs='data-change="row" data-month="'+k+'" data-key="'+key+'" data-index="'+i+'" data-field="'+f+'"';if(t==='b')return '<input type="checkbox" '+(r[f]?'checked':'')+' '+attrs+' aria-label="Pago">';if(t==='n')return '<input class="cell-input numeric" type="number" min="0" step=".01" value="'+(+r[f]||0)+'" '+attrs+'>';if(t==='d')return '<input class="cell-input day" type="number" min="1" max="31" value="'+(+r[f]||1)+'" '+attrs+'>';if(t==='tipo'||t==='cat'){let opts=t==='tipo'?S.tipos:S.cats;return '<select class="cell-select" '+attrs+'>'+[...new Set([...opts,r[f]])].map(o=>'<option '+(o===r[f]?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select>'}return '<input class="cell-input" value="'+esc(r[f])+'" '+attrs+' aria-label="'+label+'">'}
function section(k,key,title,desc,extra=''){let all=M(k)[key],cs=cols[key],rows=all.map((r,i)=>({r,i})).filter(({r})=>{let date=k+'-'+String(Math.max(1,Math.min(31,+r.dia||1))).padStart(2,'0');return(!dateFilter.from||date>=dateFilter.from)&&(!dateFilter.to||date<=dateFilter.to)}).sort((a,b)=>key==='fixos'?((a.r.pago?1:0)-(b.r.pago?1:0)||(+a.r.dia||1)-(+b.r.dia||1)):key==='parcelas'?((a.r.pago?1:0)-(b.r.pago?1:0)||(+a.r.dia||1)-(+b.r.dia||1)):0),total=rows.reduce((a,x)=>a+(+x.r.valor||0),0);return '<section class="panel"><div class="panel-head"><div><h2>'+title+'</h2><p>'+desc+'</p></div>'+extra+'</div><div class="table-wrap"><table><thead><tr>'+cs.map(c=>'<th>'+c[1]+'</th>').join('')+'<th></th></tr></thead><tbody>'+rows.map(({r,i})=>'<tr>'+cs.map(c=>'<td>'+cell(k,key,i,c,r)+'</td>').join('')+'<td><button class="icon-button" data-action="delete-row" data-month="'+k+'" data-key="'+key+'" data-index="'+i+'" aria-label="Excluir lançamento">×</button></td></tr>').join('')+'<tr class="total-row"><td colspan="'+(cs.length-1)+'">Total exibido · '+rows.length+' de '+all.length+'</td><td class="num">'+brl(total)+'</td><td></td></tr></tbody></table></div><div class="panel-foot"><span>'+rows.length+' lançamento(s) no filtro</span>'+button('＋ Adicionar','add-row','text','data-month="'+k+'" data-key="'+key+'"')+'</div></section>'}

function donut(by,total){let it=Object.entries(by).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);if(!total)return '<p class="empty">Adicione gastos para ver a distribuição.</p>';let off=0,C=2*Math.PI*43;let arcs=it.map(([c,v])=>{let l=v/total*C,s='<circle r="43" cx="55" cy="55" fill="none" stroke="'+color(c)+'" stroke-width="17" stroke-dasharray="'+l+' '+(C-l)+'" stroke-dashoffset="'+(-off)+'" transform="rotate(-90 55 55)"/>';off+=l;return s}).join('');return '<div class="chart"><svg viewBox="0 0 110 110">'+arcs+'<text x="55" y="52" text-anchor="middle" class="donut-label">GASTOS</text><text x="55" y="66" text-anchor="middle" class="donut-value">'+Math.round(total)+'</text></svg><div class="legend">'+it.map(([c,v])=>'<div><i style="background:'+color(c)+'"></i><span>'+esc(c)+'</span><b>'+((v/total)*100).toFixed(1).replace('.',',')+'%</b></div>').join('')+'</div></div>'}
function monthView(k){let c=calc(k),m=c.m,cats=[...new Set([...S.cats.filter(x=>c.cats[x]||m.esperado[x]),...Object.keys(c.cats)])];return head('PLANEJAMENTO MENSAL',full(k),'Entradas, saídas e escolhas financeiras do mês.',button('← Visão geral','go-panel')+button('Calendário','go-calendario','secondary')+button('＋ Novo mês','new-month','secondary')+button('Duplicar mês','duplicate-month','secondary','data-month="'+k+'"')+button('Renomear','rename-month','text','data-month="'+k+'"')+button('Excluir mês','delete-month','text','data-month="'+k+'"'))+'<section class="panel date-filter-panel"><div class="panel-head"><div><h2>Filtrar despesas por vencimento</h2><p>O filtro afeta as listas e os totais das despesas abaixo.</p></div><button class="button text" data-action="clear-date-filter">Limpar filtro</button></div><div class="date-filter-fields"><label>De <input type="date" value="'+dateFilter.from+'" data-change="date-filter" data-field="from"></label><label>Até <input type="date" value="'+dateFilter.to+'" data-change="date-filter" data-field="to"></label></div></section><div class="metrics">'+metric('Entradas',brl(c.entradas),'Salário, extras e benefícios','green')+metric('Gastos',brl(c.gasto),'Despesas lançadas')+metric('Saldo projetado',brl(c.saldo),'Após gastos e reservas',c.saldo<0?'red':'green')+metric('Reservas',brl(c.inv),'Investimentos e dinheiro guardado')+'</div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Entradas</h2><p>Valores previstos</p></div></div><div class="form-row"><label>Salário</label>'+numInput(k,'salary',m.salary)+'</div><div class="form-row"><label>Bônus e extras</label>'+numInput(k,'bonus',m.bonus)+'</div><div class="form-row"><label>Vale-refeição</label>'+numInput(k,'valeRefeicao',m.valeRefeicao)+'</div><div class="form-row"><label>Vale-alimentação</label>'+numInput(k,'valeAlimentacao',m.valeAlimentacao)+'</div><div class="form-row"><label>Vale-reembolso</label>'+numInput(k,'valeReembolso',m.valeReembolso)+'</div><div class="sumline"><span>Total</span><b>'+brl(c.entradas)+'</b></div></section><section class="panel"><div class="panel-head"><div><h2>Reservas e investimentos</h2><p>Dinheiro separado do orçamento</p></div></div><div class="form-row"><label>Reserva</label>'+numInput(k,'reserva',m.reserva)+'</div><div class="form-row"><label>Renda fixa</label>'+numInput(k,'rendaFixa',m.rendaFixa)+'</div><div class="sumline"><span>Total</span><b>'+brl(c.inv)+'</b></div></section></div><div class="section-heading"><div><p class="eyebrow">MOVIMENTAÇÕES</p><h2>Organize o mês</h2></div><span>Edite os campos diretamente.</span></div>'+section(k,'gastos','Gastos variáveis','Compras, alimentação, transporte e outras despesas')+'<div class="grid2">'+section(k,'fixos','Contas e despesas fixas','Marque o que já foi pago',button('Copiar mês anterior','copy-prev','text','data-month="'+k+'"'))+section(k,'parcelas','Cartão e parcelas','Compras parceladas e compromissos',button('Gerar próximas parcelas','generate-installments','text','data-month="'+k+'"'))+'</div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Gastos por categoria</h2><p>Planejado versus realizado</p></div>'+button('＋ Categoria','new-cat','text')+'</div><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Planejado</th><th>Realizado</th><th>%</th></tr></thead><tbody>'+cats.map(x=>'<tr><td><span class="catname"><i style="background:'+color(x)+'"></i>'+esc(x)+'</span></td><td><input class="cell-input numeric" type="number" min="0" value="'+(m.esperado[x]||'')+'" data-change="expected" data-month="'+k+'" data-category="'+esc(x)+'"></td><td class="num '+(m.esperado[x]&&(c.cats[x]||0)>m.esperado[x]?'text-red':'')+'">'+brl(c.cats[x])+'</td><td class="num">'+(c.gasto?((c.cats[x]||0)/c.gasto*100).toFixed(1):'0.0')+'%</td></tr>').join('')+'</tbody></table></div>'+donut(c.cats,c.gasto)+'</section><section class="panel"><div class="panel-head"><div><h2>Formas de pagamento</h2><p>Distribuição das saídas</p></div></div>'+(Object.entries(c.types).sort((a,b)=>b[1]-a[1]).map(([t,v])=>'<div class="type-row"><span>'+esc(t)+'</span><div><i style="width:'+(c.gasto?v/c.gasto*100:0)+'%"></i></div><b>'+brl(v)+'</b></div>').join('')||'<p class="empty">Nenhum pagamento lançado.</p>')+'</section></div>'}
function panelView(){let rows=S.keys.map(k=>({k,...calc(k)})),sum=f=>rows.reduce((a,r)=>a+f(r),0),debt=S.debts.reduce((a,d)=>a+d.valor,0),paid=S.debts.reduce((a,d)=>a+d.historico.reduce((n,p)=>n+(+p.valor||0),0),0),initial=S.debts.reduce((a,d)=>a+d.inicial,0),max=Math.max(1,...rows.map(r=>Math.max(r.entradas,r.gasto)));return head('SEU ESPAÇO FINANCEIRO','Olá, '+esc(S.profile?.chamado||'Caio')+'.','Bom ter você por aqui. Vamos deixar seu dinheiro trabalhar a favor dos seus planos.',button('＋ Novo gasto','go-current','primary'))+'<section class="hero"><div><p class="eyebrow light">SEU PRÓXIMO CAPÍTULO COMEÇA AQUI</p><h2>Menos aperto.<br>Mais controle.</h2><p>Um passo de cada vez. Acompanhe seus compromissos, celebre os avanços e transforme seus planos em realidade.</p></div><button type="button" class="hero-stat hero-stat-action" data-action="go-projecao"><span>Saldo projetado no período</span><strong>'+brl(sum(r=>r.saldo))+'</strong><small>Entradas − gastos − reservas · Ver projeção anual ↗</small></button></section><div class="metrics">'+metric('Entradas previstas',brl(sum(r=>r.entradas)),'Período planejado')+metric('Saldo devedor',brl(debt),'Dívidas em aberto','red')+metric('Pagamentos registrados',brl(paid),'Histórico de quitação','green')+metric('Saldo após despesas',brl(sum(r=>r.saldo)),'Projeção atual',sum(r=>r.saldo)<0?'red':'green')+'</div><div class="grid2"><section class="panel"><div class="panel-head"><div><p class="eyebrow">VISÃO DO PERÍODO</p><h2>Entradas e gastos</h2><p>Selecione uma coluna para abrir o mês.</p></div></div><div class="chart-key"><span>● Entradas</span><span>● Gastos</span></div><div class="bars">'+rows.map(r=>'<button data-action="go-month" data-month="'+r.k+'" title="'+full(r.k)+'"><span class="bar-pair"><i class="income" style="height:'+r.entradas/max*100+'%"></i><i class="expense" style="height:'+r.gasto/max*100+'%"></i></span><small>'+short(r.k).split('/')[0]+'</small></button>').join('')+'</div></section><section class="panel debt-focus"><div class="panel-head"><div><p class="eyebrow">PRIORIDADE</p><h2>Plano para quitar dívidas</h2><p>Registre pagamentos e acompanhe cada saldo.</p></div><span class="pill">'+S.debts.filter(d=>d.valor>0).length+' ativas</span></div><div class="sumline"><span>Saldo devedor</span><b class="text-red">'+brl(debt)+'</b></div><div class="progress"><i style="width:'+(initial?Math.min(100,paid/initial*100):0)+'%"></i></div><div class="progress-meta"><span>'+(initial?Math.round(paid/initial*100):0)+'% quitado*</span><span>'+brl(paid)+' pago</span></div>'+button('Abrir controle de dívidas →','go-debts','primary full')+'<p class="micro">*Considera valores iniciais registrados e pagamentos lançados no aplicativo.</p></section></div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Resumo mensal</h2><p>Selecione um mês para abrir os detalhes</p></div></div><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Entradas</th><th>Gastos</th><th>Saldo</th></tr></thead><tbody>'+rows.map(r=>'<tr class="click-row" data-action="go-month" data-month="'+r.k+'"><td>'+full(r.k)+'</td><td class="num">'+brl(r.entradas)+'</td><td class="num">'+brl(r.gasto)+'</td><td class="num '+(r.saldo<0?'text-red':'text-green')+'">'+brl(r.saldo)+'</td></tr>').join('')+'</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Seus dados</h2><p>Backup e portabilidade</p></div></div><p class="body-copy">Tudo fica salvo neste navegador. Exporte um backup antes de limpar os dados ou trocar de aparelho.</p><div class="button-stack">'+button('↓ Exportar backup JSON','export')+button('↓ Exportar CSV','export-csv')+button('↓ Gerar PDF','export-pdf')+button('↑ Importar backup','import')+button('Zerar lançamentos dos meses','clear-all-months','text')+'</div><p class="micro">A sincronização entre dispositivos ficará para uma próxima etapa.</p></section></div>'}
function debtView(){let total=S.debts.reduce((a,d)=>a+d.valor,0),initial=S.debts.reduce((a,d)=>a+d.inicial,0),paid=S.debts.reduce((a,d)=>a+d.historico.reduce((n,p)=>n+(+p.valor||0),0),0),done=S.debts.filter(d=>d.valor<=0).length,arr=S.debts.filter(d=>filter==='todas'||(filter==='ativas'?d.valor>0:d.valor<=0)).sort((a,b)=>b.valor-a.valor);return head('PLANO DE QUITAÇÃO','Dívidas, sem perder o controle.','Acompanhe saldos devedores, registre pagamentos e veja seu progresso.',button('＋ Nova dívida','new-debt','primary'))+'<div class="metrics">'+metric('Saldo devedor',brl(total),'O que falta pagar','red')+metric('Valor inicial',brl(initial),'Referência do progresso')+metric('Total pago',brl(paid),'Pagamentos registrados','green')+metric('Dívidas quitadas',done+' de '+S.debts.length,'Compromissos concluídos')+'</div><section class="panel"><div class="panel-head"><div><h2>Seu caminho até quitar</h2><p>O saldo é atualizado a cada pagamento registrado.</p></div></div><div class="progress large"><i style="width:'+(initial?Math.min(100,paid/initial*100):0)+'%"></i></div><div class="progress-meta"><span>'+(initial?Math.round(paid/initial*100):0)+'% quitado</span><b>'+brl(total)+' restante</b></div><div class="filter-row"><span>Mostrar</span><div class="filters">'+[['todas','Todas'],['ativas','Em aberto'],['quitadas','Quitadas']].map(([v,t])=>'<button class="'+(filter===v?'selected':'')+'" data-action="filter" data-filter="'+v+'">'+t+'</button>').join('')+'</div></div></section><div class="debts">'+(arr.map(d=>{let i=S.debts.indexOf(d),progress=d.inicial?Math.max(0,Math.min(100,(d.inicial-d.valor)/d.inicial*100)):0,h=d.historico.slice().sort((a,b)=>String(b.data).localeCompare(String(a.data)));return '<article class="debt-card"><div class="debt-top"><div><span class="debt-index">DÍVIDA '+String(i+1).padStart(2,'0')+'</span><h2>'+esc(d.nome)+'</h2><p>'+(d.vencimento?'Vencimento dia '+esc(d.vencimento):'Vencimento não informado')+'</p></div>'+button('Editar','edit-debt','text','data-index="'+i+'"')+'</div><div class="debt-amounts"><div><span>Saldo atual</span><strong class="'+(d.valor>0?'text-red':'text-green')+'">'+brl(d.valor)+'</strong></div><div><span>Valor inicial</span><strong>'+brl(d.inicial)+'</strong></div></div><div class="progress"><i style="width:'+progress+'%"></i></div><div class="progress-meta"><span>'+Math.round(progress)+'% quitado</span><span>'+brl(Math.max(0,d.inicial-d.valor))+' amortizado</span></div>'+(d.observacao?'<p class="debt-note">'+esc(d.observacao)+'</p>':'')+'<div class="debt-actions">'+(d.valor>0?button('＋ Registrar pagamento','pay-debt','primary','data-index="'+i+'"'):'<span class="paid">✓ Dívida quitada</span>')+button('Histórico ('+h.length+')','history','secondary','data-index="'+i+'"')+'</div><div id="history-'+i+'" class="history" hidden>'+(h.length?'<h3>Pagamentos registrados</h3>'+h.map(p=>'<div class="history-row"><span><b>'+brl(p.valor)+'</b><small>'+esc(p.data||'Data não informada')+(p.nota?' · '+esc(p.nota):'')+'</small></span>'+button('×','remove-payment','text','data-index="'+i+'" data-payment="'+d.historico.indexOf(p)+'"')+'</div>').join(''):'<p class="empty">Nenhum pagamento registrado.</p>')+'</div></article>'}).join('')||'<section class="panel empty">Nenhuma dívida nesta seleção.</section>')+'</div><p class="micro">Para dívidas antigas, o saldo inicial é estimado a partir do valor cadastrado hoje. Edite o valor inicial se souber o total original.</p>'}
function goalsView(){return head('PLANOS E METAS','Dê um destino ao seu dinheiro.','Acompanhe objetivos e aportes mensais.',button('＋ Nova meta','new-goal','primary'))+'<div class="goal-grid">'+((S.goals||[]).map(g=>{let p=S.keys.reduce((n,k)=>n+M(k).aportesMetas.filter(a=>a.goalId===g.id).reduce((z,a)=>z+(+a.valor||0),0),0),pct=g.alvo?Math.min(100,p/g.alvo*100):0;return '<article class="panel"><p class="eyebrow">OBJETIVO FINANCEIRO</p><h2>'+esc(g.nome)+'</h2><p>'+esc(g.descricao||'')+'</p><strong>'+brl(p)+' / '+brl(g.alvo)+'</strong><div class="progress"><i style="width:'+pct+'%"></i></div><div class="progress-meta"><span>'+Math.round(pct)+'% concluído</span><b>Faltam '+brl(Math.max(0,g.alvo-p))+'</b></div><p class="micro">'+(g.prazo?'Prazo: '+esc(g.prazo):'Sem prazo definido')+'</p>'+button('＋ Registrar aporte','add-goal-contribution','primary')+button('Excluir meta','delete-goal','text','data-id="'+g.id+'"')+'</article>'}).join('')||'<section class="panel empty">Cadastre sua primeira meta.</section>')+'</div>'}
function newGoal(){let nome=(prompt('Nome da meta:')||'').trim();if(!nome)return;let v=prompt('Valor desejado (R$):','');if(v===null)return;let alvo=+v.replace(',','.');if(!Number.isFinite(alvo)||alvo<=0)return alert('Informe um valor válido.');let prazo=prompt('Prazo opcional (AAAA-MM):','');if(prazo===null)return;let descricao=prompt('Descrição opcional:','')||'';S.goals.push({id:'g'+Date.now(),nome,alvo,prazo,descricao});save();render()}
function addGoalContribution(k){if(!S.goals.length)return alert('Cadastre uma meta primeiro.');if(!S.months[k]){k=(prompt('Em qual mês registrar o aporte? (AAAA-MM)',S.keys[0]||today)||'').trim();if(!/^[0-9]{4}-(0[1-9]|1[0-2])$/.test(k))return alert('Informe o mês no formato AAAA-MM.');if(!S.months[k]){S.months[k]={salary:0,bonus:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[]};S.keys.push(k);S.keys.sort()}}let n=prompt('Número da meta:\n'+S.goals.map((g,i)=>(i+1)+'. '+g.nome).join('\n'),'1');if(n===null)return;let g=S.goals[+n-1];if(!g)return alert('Meta inválida.');let v=prompt('Valor do aporte (R$):','');if(v===null)return;let valor=+v.replace(',','.');if(!Number.isFinite(valor)||valor<=0)return alert('Valor inválido.');M(k).aportesMetas.push({id:'a'+Date.now(),goalId:g.id,valor,dia:1});save();render()}
function banksView(){return head('BANCOS E CONTAS','Onde seu dinheiro está.','Cadastre bancos, carteiras digitais e corretoras. Nunca informe senhas ou códigos de acesso.',button('＋ Adicionar conta','new-bank','primary'))+'<div class="goal-grid">'+(S.banks.map(b=>'<article class="panel"><p class="eyebrow">'+esc(b.tipo)+'</p><h2>'+esc(b.nome)+'</h2><p>'+esc(b.identificador||'')+'</p><p class="micro">'+esc(b.nota||'')+'</p>'+button('Excluir','delete-bank','text','data-id="'+b.id+'"')+'</article>').join('')||'<section class="panel empty">Nenhuma conta cadastrada.</section>')+'</div>'}
function newBank(){openForm('Adicionar banco ou conta',[{name:'nome',label:'Banco, carteira ou corretora',required:true},{name:'tipo',label:'Tipo de instituição'},{name:'identificador',label:'Identificação opcional (sem senhas)'},{name:'nota',label:'Observações',type:'textarea'}],{tipo:'Banco'},v=>{S.banks.push({id:'b'+Date.now(),nome:v.nome,tipo:v.tipo||'Banco',identificador:v.identificador,nota:v.nota});save()})}
function subscriptionsView(){return head('ASSINATURAS','Configure uma vez. Planeje todo mês.','Cadastre a recorrência uma vez; ela será incluída no mês inicial e no seguinte.',button('＋ Nova assinatura','new-subscription','primary'))+'<section class="panel subscriptions-panel"><div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Dia</th><th>Valor</th><th>Pagamento</th><th>Categoria</th><th>Início</th></tr></thead><tbody>'+(S.subscriptions.map(s=>'<tr><td>'+esc(s.nome)+'</td><td>'+s.dia+'</td><td>'+brl(s.valor)+'</td><td>'+esc(s.tipo)+'</td><td>'+esc(s.cat)+'</td><td>'+esc(s.inicio||'Imediato')+'</td></tr>').join('')||'<tr><td colspan="6">Cadastre uma despesa recorrente.</td></tr>')+'</tbody></table></div><div class="subscription-actions">'+button('＋ Nova assinatura','new-subscription','secondary')+button('Aplicar ao mês atual e ao próximo','apply-subscriptions','primary')+'</div></section>'}
function newSubscription(){let start=S.keys.includes(cur)?cur:today;openForm('Nova assinatura',[{name:'nome',label:'Nome da despesa recorrente',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'dia',label:'Dia da cobrança',type:'number',min:1,max:31,step:1,required:true},{name:'tipo',label:'Forma de pagamento'},{name:'cat',label:'Categoria'},{name:'inicio',label:'Começa em qual mês?',type:'month',required:true},{name:'observacao',label:'Observações',type:'textarea'}],{valor:0,dia:1,tipo:'Débito',cat:'Assinaturas',inicio:start},v=>{let sub={id:'s'+Date.now(),nome:v.nome,valor:+v.valor||0,dia:+v.dia||1,tipo:v.tipo||'Débito',cat:v.cat||'Assinaturas',observacao:v.observacao,ativo:true,inicio:v.inicio};S.subscriptions.push(sub);let [y,mo]=v.inicio.split('-').map(Number);[0,1].forEach(offset=>{let dt=new Date(y,mo-1+offset,1),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0'),m=M(k);if(!m.fixos.some(x=>x.subscriptionId===sub.id))m.fixos.push({nome:sub.nome,dia:sub.dia,tipo:sub.tipo,cat:sub.cat,valor:sub.valor,pago:false,subscriptionId:sub.id})});save()})}
function applySubscriptions(){let base=S.keys.includes(cur)?cur:today,[y,mo]=base.split('-').map(Number),months=[base,(()=>{let d=new Date(y,mo,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')})()],added=0;months.forEach(k=>{let m=M(k);S.subscriptions.filter(sub=>sub.ativo!==false&&(!sub.inicio||k>=sub.inicio)).forEach(sub=>{if(!m.fixos.some(x=>x.subscriptionId===sub.id||x.nome===sub.nome)){m.fixos.push({nome:sub.nome,dia:sub.dia,tipo:sub.tipo,cat:sub.cat,valor:sub.valor,pago:false,subscriptionId:sub.id});added++}})});save();render();alert(added+' conta(s) recorrente(s) adicionada(s) aos meses selecionados.')}
function annualView(){let y=projectionYear,rows=Array.from({length:12},(_,i)=>{let k=y+'-'+String(i+1).padStart(2,'0'),m=S.months[k],all=m?[...(m.gastos||[]),...(m.fixos||[]),...(m.parcelas||[])]:[],entradas=m?(+m.salary||0)+(+m.bonus||0)+(+m.valeRefeicao||0)+(+m.valeAlimentacao||0)+(+m.valeReembolso||0):0,gasto=all.reduce((n,r)=>n+(+r.valor||0),0),reservas=m?(+m.reserva||0)+(+m.rendaFixa||0)+(m.aportesMetas||[]).reduce((n,a)=>n+(+a.valor||0),0):0;return{k,exists:!!m,entradas,gasto,reservas,saldo:entradas-gasto-reservas}}),cum=0;rows.forEach(r=>{cum+=r.saldo;r.acumulado=cum});let total=f=>rows.reduce((n,r)=>n+r[f],0);return head('PROJEÇÃO ANUAL','Veja o ano antes de vivê-lo.','A projeção considera os lançamentos existentes; meses vazios aparecem como não planejados.',button('← Visão geral','go-panel'))+'<section class="panel"><div class="panel-head"><div><h2>Planejamento de '+y+'</h2><p>Saldo mensal e acumulado são indicadores diferentes.</p></div><select data-change="projection-year">'+[y-1,y,y+1,...S.keys.map(k=>+k.slice(0,4))].filter((v,i,a)=>a.indexOf(v)===i).sort((a,b)=>a-b).map(v=>'<option value="'+v+'" '+(v===y?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="metrics">'+metric('Entradas anuais',brl(total('entradas')),'Ano selecionado')+metric('Gastos anuais',brl(total('gasto')),'Despesas lançadas')+metric('Reservas e metas',brl(total('reservas')),'Dinheiro separado')+metric('Saldo anual',brl(total('saldo')),'Entradas − gastos − reservas',total('saldo')<0?'red':'green')+'</div>'+annualChart(rows)+'<div class="table-wrap"><table><thead><tr><th>Mês</th><th>Status</th><th>Entradas</th><th>Gastos</th><th>Reservas/metas</th><th>Saldo mensal</th><th>Acumulado</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+new Date(y,+r.k.slice(5)-1,1).toLocaleDateString('pt-BR',{month:'long'})+'</td><td>'+(r.exists?'Planejado':'Sem dados')+'</td><td>'+brl(r.entradas)+'</td><td>'+brl(r.gasto)+'</td><td>'+brl(r.reservas)+'</td><td class="'+(r.saldo<0?'text-red':'text-green')+'">'+brl(r.saldo)+'</td><td class="'+(r.acumulado<0?'text-red':'text-green')+'">'+brl(r.acumulado)+'</td><td>'+button(r.exists?'Abrir':'Planejar','go-month','text','data-month="'+r.k+'"')+'</td></tr>').join('')+'</tbody></table></div><p class="micro">Meses vazios contam como zero. O acumulado não inclui saldo bancário inicial.</p></section>'}
function calendarView(){let d=calendarDate,y=d.getFullYear(),mo=d.getMonth(),first=new Date(y,mo,1),days=new Date(y,mo+1,0).getDate(),offset=(first.getDay()+6)%7,k=y+'-'+String(mo+1).padStart(2,'0'),m=S.months[k]||{gastos:[],fixos:[],parcelas:[]},events=[];[...(m.gastos||[]),...(m.fixos||[]),...(m.parcelas||[])].forEach(r=>events.push({dia:Math.min(days,Math.max(1,+r.dia||1)),nome:r.nome,valor:+r.valor||0,pago:!!r.pago}));(S.subscriptions||[]).filter(x=>x.ativo!==false).forEach(x=>{let day=Math.min(days,Math.max(1,+x.dia||1));if(!events.some(e=>e.dia===day&&e.nome===x.nome))events.push({dia:day,nome:x.nome,valor:+x.valor||0,pago:false})});let cells=Array.from({length:offset},()=>'<div class="calendar-day blank"></div>');for(let day=1;day<=days;day++){let ev=events.filter(x=>x.dia===day),now=day===new Date().getDate()&&mo===new Date().getMonth()&&y===new Date().getFullYear();cells.push('<div class="calendar-day '+(now?'is-today':'')+'"><b>'+day+'</b>'+ev.slice(0,2).map(x=>'<small class="'+(x.pago?'is-paid':'')+'">'+esc(x.nome)+'</small>').join('')+(ev.length>2?'<small>+'+(ev.length-2)+' mais</small>':'')+'</div>')}return head('CALENDÁRIO FINANCEIRO','Seus compromissos, dia a dia.','Contas, parcelas e assinaturas previstas.',button('← Visão geral','go-panel'))+'<section class="panel"><div class="calendar-toolbar">'+button('← Anterior','calendar-prev','secondary')+'<h2>'+first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})+'</h2>'+button('Próximo →','calendar-next','secondary')+'</div><div class="calendar-grid">'+['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>'<div class="calendar-weekday">'+x+'</div>').join('')+cells.join('')+'</div><p class="micro">O dia atual fica destacado automaticamente. Assinaturas aparecem como previsão.</p></section>'}
function clearAllMonths(){if(!confirm('Zerar os lançamentos de todos os meses? Os meses, bancos, dívidas, metas e assinaturas serão mantidos.'))return;S.keys.forEach(k=>{let m=S.months[k]||{};S.months[k]={salary:0,bonus:0,valeRefeicao:0,valeAlimentacao:0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[],nomeMes:m.nomeMes||''}});save();go('painel')}
function notifyDueToday(){let d=new Date(),k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),day=d.getDate(),m=S.months[k];if(!m)return;let due=[...(m.gastos||[]),...(m.fixos||[]),...(m.parcelas||[])].filter(x=>(+x.dia||1)===day&&!x.pago);if(due.length)window.setTimeout(()=>alert('Hoje você tem '+due.length+' compromisso(s) financeiro(s):\n'+due.map(x=>'• '+x.nome+' — '+brl(x.valor)).join('\n')),600)}
function render(){document.body.classList.toggle('privacy-hidden',!privacyVisible);let nav=[['painel','Visão geral','▦'],['calendario','Calendário','▦'],['metas','Planos e metas','◎'],['assinaturas','Assinaturas','↻'],['bancos','Bancos e contas','◈'],['projecao','Projeção anual','▤'],['dividas','Dívidas','↘']];$('#tabs').innerHTML='<div class="nav-group"><span class="nav-label">MENU PRINCIPAL</span>'+nav.map(([k,l,ic])=>'<button class="nav-item '+(cur===k?'active':'')+'" data-action="'+(k==='painel'?'go-panel':k==='dividas'?'go-debts':'go-'+k)+'"><span class="nav-icon">'+ic+'</span>'+l+(k==='dividas'?'<b class="count">'+S.debts.filter(d=>d.valor>0).length+'</b>':'')+'</button>').join('')+'</div><div class="nav-group month-nav"><div class="nav-month-head"><span class="nav-label">PLANEJAMENTO MENSAL</span><button class="nav-add-month" data-action="new-month" aria-label="Adicionar mês">＋</button></div>'+S.keys.map(k=>'<button class="nav-item month-item '+(cur===k?'active':'')+'" data-action="go-month" data-month="'+k+'"><span class="month-dot"></span>'+esc(full(k))+'</button>').join('')+'</div><div class="nav-status">● Salvamento local ativo</div>';$('#app').innerHTML='<button type="button" class="privacy-toggle" data-action="toggle-privacy" aria-label="'+(privacyVisible?'Ocultar valores':'Mostrar valores')+'" title="'+(privacyVisible?'Ocultar valores':'Mostrar valores')+'">'+(privacyVisible?'◉':'◎')+' <span>'+(privacyVisible?'Ocultar valores':'Mostrar valores')+'</span></button>'+(cur==='painel'?panelView():cur==='calendario'?calendarView():cur==='dividas'?debtView():cur==='metas'?goalsView():cur==='assinaturas'?subscriptionsView():cur==='bancos'?banksView():cur==='projecao'?annualView():monthView(cur));let a=$('#tabs .active');if(a&&a.classList.contains('month-item')&&innerWidth>620)a.scrollIntoView({block:'nearest'})}
function go(k){cur=k;render();scrollTo({top:0,behavior:'smooth'})}
function upd(k,key,i,f,v){let r=M(k)[key][i],t=cols[key].find(c=>c[0]===f)[2];r[f]=t==='n'||t==='d'?(+v||0):v;save();render()}
function setM(k,f,v){M(k)[f]=Math.max(0,+v||0);save();render()}
function setEsp(k,c,v){M(k).esperado[c]=Math.max(0,+v||0);save();render()}
function addRow(k,key){let r={nome:'',dia:1,tipo:S.tipos[0]||'Débito',cat:S.cats[0]||'Outros',valor:0};if(key==='fixos')r.pago=false;if(key==='parcelas')r.parc='1/1';M(k)[key].push(r);save();render()}
function newMonth(){let k=(prompt('Informe o mês no formato AAAA-MM (ex.: 2027-11):','')||'').trim();if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(k))return alert('Use o formato AAAA-MM, como 2027-11.');if(S.months[k])return alert('Esse mês já existe.');let[y,m]=k.split('-');S.months[k]={salary:0,bonus:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},nomeMes:''};S.keys.push(k);S.keys=[...new Set(S.keys)].sort();let nome=(prompt('Nome para exibir (opcional):',new Date(+y,+m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))||'').trim();if(nome)S.months[k].nomeMes=nome;cur=k;save();render()}
function renameMonth(k){let name=prompt('Nome que deseja exibir para este mês:',M(k).nomeMes||full(k));if(name===null)return;M(k).nomeMes=name.trim();save();render()}
function duplicateMonth(source){let target=(prompt('Qual mês receberá a cópia? Use AAAA-MM:', '')||'').trim();if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(target))return alert('Use o formato AAAA-MM, como 2027-11.');if(S.months[target])return alert('Esse mês já existe. Escolha outro mês.');let src=M(source),[y,m]=target.split('-');S.months[target]={...clone(src),nomeMes:'',gastos:clone(src.gastos||[]),fixos:(src.fixos||[]).map(r=>({...r,pago:false})),parcelas:clone(src.parcelas||[]),esperado:clone(src.esperado||{})};S.keys.push(target);S.keys=[...new Set(S.keys)].sort();let name=(prompt('Nome para exibir (opcional):',new Date(+y,+m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))||'').trim();if(name)S.months[target].nomeMes=name;cur=target;save();render()}
function deleteMonth(k){if(S.keys.length<=1)return alert('Mantenha pelo menos um mês.');if(!confirm('Excluir '+full(k)+' e todos os seus lançamentos? Esta ação não pode ser desfeita.'))return;delete S.months[k];S.keys=S.keys.filter(x=>x!==k);cur='painel';save();render()}
function generateInstallments(k){let rows=M(k).parcelas.filter(r=>/^[ ]*[0-9]+[ ]*\/[ ]*[0-9]+[ ]*$/.test(String(r.parc||''))&&r.nome&&(+r.valor||0)>0);if(!rows.length)return alert('Preencha descrição, valor e parcela no formato 1/12.');let created=0;rows.forEach(r=>{let [n,total]=String(r.parc).split('/').map(v=>parseInt(v.trim(),10));if(!n||!total||n>=total)return;let [y,mo]=k.split('-').map(Number);for(let part=n+1;part<=total;part++){mo++;if(mo>12){mo=1;y++}let next=y+'-'+String(mo).padStart(2,'0');if(!S.months[next])S.months[next]={salary:0,bonus:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[]};if(!S.months[next].parcelas.some(x=>x.nome===r.nome+' (parcela '+part+'/'+total+')')){S.months[next].parcelas.push({...clone(r),nome:r.nome+' (parcela '+part+'/'+total+')',parc:part+'/'+total});created++}}});S.keys=[...new Set(S.keys)].sort();save();render();alert(created+' parcela(s) criada(s) nos meses seguintes.')}
function copyPrev(k){let i=S.keys.indexOf(k),p=S.months[S.keys[i-1]],m=M(k);if(!p)return alert('Não há mês anterior.');if(!confirm('Copiar contas fixas e parcelas do mês anterior?'))return;p.fixos.forEach(r=>m.fixos.push({...r,pago:false}));p.parcelas.forEach(r=>{let[a,b]=String(r.parc||'').split('/').map(Number);if(a&&b&&a<b)m.parcelas.push({...r,parc:(a+1)+'/'+b})});save();render()}
function exportData(){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(S,null,2)],{type:'application/json'}));a.href=u;a.download='financas-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importData(e){let f=e.target.files?.[0];if(!f)return;try{let j=JSON.parse(await f.text());if(!valid(j))throw 0;if(!confirm('Importar substituirá os dados deste navegador. Você já exportou um backup atual?'))return;S=normalize(j);cur='painel';save();render();alert('Backup importado.')}catch(e){alert('Arquivo inválido ou incompatível. Nenhum dado foi importado.')}finally{e.target.value=''}}
function restore(){if(confirm('Isso substituirá os dados atuais pelos dados iniciais. Exporte um backup antes. Continuar?')){S=normalize(clone(window.SEED));cur='painel';save();render()}}
function newDebt(){openForm('Nova dívida',[{name:'nome',label:'Nome da dívida',required:true},{name:'valor',label:'Saldo devedor (R$)',type:'number',min:0,step:'.01',required:true},{name:'inicial',label:'Valor total original (R$)',type:'number',min:0,step:'.01'},{name:'parcelada',label:'Parcelada? 1 sim / 0 não',type:'number',min:0,max:1,step:1},{name:'valorParcela',label:'Valor da parcela (R$)',type:'number',min:0,step:'.01'},{name:'totalParcelas',label:'Quantidade de parcelas',type:'number',min:0,step:1},{name:'dataInicio',label:'Primeiro vencimento AAAA-MM-DD'},{name:'dia',label:'Dia de vencimento',type:'number',min:1,max:31,step:1},{name:'tipo',label:'Forma de pagamento'},{name:'cat',label:'Categoria'},{name:'observacao',label:'Observações',type:'textarea'}],{valor:0,inicial:0,parcelada:0,valorParcela:0,totalParcelas:0,dataInicio:today+'-01',dia:10,tipo:'Débito',cat:'Dívidas'},v=>{let d={id:'d'+Date.now(),...v,valor:+v.valor||0,inicial:+v.inicial||+v.valor||0,parcelada:+v.parcelada===1,valorParcela:+v.valorParcela||0,totalParcelas:+v.totalParcelas||0,dia:+v.dia||10,historico:[],vencimento:String(+v.dia||10)};S.debts.push(d);if(d.parcelada&&d.totalParcelas&&d.valorParcela)generateDebtInstallments(d);save()})}
function generateDebtInstallments(d){S.keys.forEach(k=>{if(S.months[k])S.months[k].parcelas=(S.months[k].parcelas||[]).filter(x=>x.debtId!==d.id)});let start=/^\d{4}-\d{2}-\d{2}$/.test(d.dataInicio||'')?new Date(d.dataInicio+'T12:00:00'):new Date(),count=Math.min(360,+d.totalParcelas||0);for(let i=0;i<count;i++){let dt=new Date(start.getFullYear(),start.getMonth()+i,Math.min(28,+d.dia||start.getDate())),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0');if(!S.months[k]){S.months[k]={salary:0,bonus:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[]};S.keys.push(k)}S.months[k].parcelas.push({debtId:d.id,nome:d.nome,tipo:d.tipo||'Débito',cat:d.cat||'Dívidas',valor:+d.valorParcela||0,dia:dt.getDate(),parc:(i+1)+'/'+count,pago:false})}S.keys=[...new Set(S.keys)].sort()}
function editDebt(i){let d=S.debts[i];openForm('Editar dívida',[{name:'nome',label:'Nome da dívida',required:true},{name:'valor',label:'Saldo devedor (R$)',type:'number',min:0,step:'.01',required:true},{name:'inicial',label:'Valor total original (R$)',type:'number',min:0,step:'.01'},{name:'parcelada',label:'Parcelada? 1 sim / 0 não',type:'number',min:0,max:1,step:1},{name:'valorParcela',label:'Valor da parcela (R$)',type:'number',min:0,step:'.01'},{name:'totalParcelas',label:'Quantidade de parcelas',type:'number',min:0,step:1},{name:'dataInicio',label:'Primeiro vencimento AAAA-MM-DD'},{name:'dia',label:'Dia de vencimento',type:'number',min:1,max:31,step:1},{name:'tipo',label:'Forma de pagamento'},{name:'cat',label:'Categoria'},{name:'observacao',label:'Observações',type:'textarea'}],{...d,parcelada:d.parcelada?1:0},v=>{Object.assign(d,v,{valor:+v.valor||0,inicial:+v.inicial||+v.valor||0,parcelada:+v.parcelada===1,valorParcela:+v.valorParcela||0,totalParcelas:+v.totalParcelas||0,dia:+v.dia||10});d.vencimento=String(d.dia);if(d.parcelada&&d.totalParcelas&&d.valorParcela)generateDebtInstallments(d);save()})}
function payDebt(i){let d=S.debts[i],raw=prompt('Valor pago em '+d.nome+' (R$):','');if(raw===null)return;let v=+raw.replace(',','.');if(!Number.isFinite(v)||v<=0)return alert('Informe um valor válido maior que zero.');if(v>d.valor&&!confirm('O pagamento supera o saldo. Registrar e quitar a dívida?'))return;let data=prompt('Data (AAAA-MM-DD):',new Date().toISOString().slice(0,10));if(data===null)return;let nota=prompt('Observação opcional:','');if(nota===null)return;v=Math.min(v,d.valor);d.historico.push({valor:v,data:data.trim()||new Date().toISOString().slice(0,10),nota:nota.trim()});d.valor=Math.max(0,Math.round((d.valor-v)*100)/100);save();render()}
function removePayment(i,j){if(!confirm('Excluir o pagamento e devolver o valor ao saldo devedor?'))return;let p=S.debts[i].historico.splice(j,1)[0];S.debts[i].valor=Math.round((S.debts[i].valor+(+p.valor||0))*100)/100;save();render()}
function clickAction(b){let a=b.dataset.action;switch(a){case'toggle-privacy':privacyVisible=!privacyVisible;render();break;case'go-panel':go('painel');break;case'edit-profile':editProfile();break;case'export-csv':exportCSV();break;case'export-pdf':exportPDF();break;case'clear-all-months':clearAllMonths();break;case'go-calendario':go('calendario');break;case'calendar-prev':calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1);render();break;case'calendar-next':calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1);render();break;case'go-projecao':go('projecao');break;case'go-debts':go('dividas');break;case'go-metas':go('metas');break;case'go-assinaturas':go('assinaturas');break;case'go-bancos':go('bancos');break;case'go-projecao':go('projecao');break;case'delete-month':deleteMonth(b.dataset.month||cur);break;case'generate-installments':generateInstallments(b.dataset.month||cur);break;case'new-goal':newGoal();break;case'delete-goal':if(confirm('Excluir esta meta?')){S.goals=S.goals.filter(g=>g.id!==b.dataset.id);save();render()}break;case'new-bank':newBank();break;case'delete-bank':if(confirm('Excluir esta conta?')){S.banks=S.banks.filter(x=>x.id!==b.dataset.id);save();render()}break;case'new-subscription':newSubscription();break;case'apply-subscriptions':applySubscriptions();break;case'add-goal-contribution':addGoalContribution(b.dataset.month||cur);break;case'go-current':go(S.keys.includes(today)?today:S.keys[0]);break;case'go-month':go(b.dataset.month);break;case'new-month':newMonth();break;case'rename-month':renameMonth(b.dataset.month||cur);break;case'duplicate-month':duplicateMonth(b.dataset.month||cur);break;case'clear-date-filter':dateFilter={from:'',to:''};render();break;case'delete-month':deleteMonth(b.dataset.month||cur);break;case'add-goal-contribution':addGoalContribution(b.dataset.month||cur);break;case'add-row':addRow(b.dataset.month,b.dataset.key);break;case'delete-row':if(confirm('Excluir este lançamento?')){M(b.dataset.month)[b.dataset.key].splice(+b.dataset.index,1);save();render()}break;case'copy-prev':copyPrev(b.dataset.month);break;case'new-cat':{let n=(prompt('Nome da nova categoria:')||'').trim();if(n&&!S.cats.includes(n)){S.cats.push(n);save();render()}break}case'export':exportData();break;case'import':$('#file').click();break;case'restore':restore();break;case'new-debt':newDebt();break;case'edit-debt':editDebt(+b.dataset.index);break;case'pay-debt':payDebt(+b.dataset.index);break;case'history':{let el=$('#history-'+b.dataset.index);if(el)el.hidden=!el.hidden;break}case'remove-payment':removePayment(+b.dataset.index,+b.dataset.payment);break;case'filter':filter=b.dataset.filter;render();break}}
$('#tabs').addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)clickAction(b);if(innerWidth<=620){$('#sidebar').classList.remove('mobile-open');$('#nav-overlay').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}});$('#menu-toggle').addEventListener('click',()=>{let open=$('#sidebar').classList.toggle('mobile-open');$('#nav-overlay').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open))});$('#nav-overlay').addEventListener('click',()=>{$('#sidebar').classList.remove('mobile-open');$('#nav-overlay').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')});
$('#app').addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)clickAction(b)});
$('#app').addEventListener('change',e=>{let el=e.target,d=el.dataset;if(d.change==='month')setM(d.month,d.field,el.value);else if(d.change==='expected')setEsp(d.month,d.category,el.value);else if(d.change==='row')upd(d.month,d.key,+d.index,d.field,el.type==='checkbox'?el.checked:el.value);else if(d.change==='date-filter'){dateFilter[d.field]=el.value;render()}else if(d.change==='projection-year'){projectionYear=+el.value;render()}else if(d.change==='projection-year'){projectionYear=+el.value;render()}});
$('#file').addEventListener('change',importData);$('#sidebar-profile').addEventListener('click',editProfile);render();notifyDueToday();if(navigator.storage?.persist)navigator.storage.persist();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
})();